package com.simon.offlinebms;
import android.content.*;
import android.database.sqlite.*;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import org.json.*;
import java.util.*;
/** Runs the actual app storage code against real SQLite through a small host adapter. */
public final class StorageHostTests{
 static int checks;static void check(boolean b,String label){if(!b)throw new AssertionError(label);checks++;}
 static Reading reading(long time,String name,String mac){Reading d=Reading.demo();return new Reading(time,d.basic,d.cells,name+" ["+mac+"]");}
 static byte[] bytes(String s){return s.getBytes(StandardCharsets.UTF_8);}
 public static void main(String[] args)throws Exception{
  Path dir=Files.createTempDirectory("bms-storage-test-");Context context=new Context(dir);long now=System.currentTimeMillis();String address="AA:BB:CC:DD:EE:01",other="AA:BB:CC:DD:EE:02";Reading legacy=reading(now-60000,"Original name",address);JSONObject oldJson=legacy.json();oldJson.remove("address");oldJson.remove("vendor");oldJson.remove("firmware_raw");
  try(SQLiteDatabase old=new SQLiteDatabase(dir.resolve("bms_history.db"))){old.execSQL("CREATE TABLE readings (id INTEGER PRIMARY KEY, timestamp INTEGER NOT NULL, device TEXT NOT NULL, soc REAL NOT NULL, power REAL NOT NULL, voltage REAL NOT NULL, payload TEXT NOT NULL)");ContentValues values=new ContentValues();values.put("timestamp",legacy.timestamp);values.put("device",legacy.device);values.put("soc",legacy.basic.soc);values.put("power",legacy.basic.power());values.put("voltage",legacy.basic.voltage);values.put("payload",oldJson.toString());old.insertOrThrow("readings",null,values);old.execSQL("PRAGMA user_version=1");}
  HistoryStore store=new HistoryStore(context);check(store.count()==1,"Upgrade preserves old reading");Reading migrated=store.latest(address);check(migrated!=null&&migrated.address.equals(address),"Old address migrated from device label");check(migrated.basic.versionText().equals("2.4"),"Old firmware text preserved");check(store.chart(address,now-3600000).size()==1,"Old graph rows migrated");
  store.add(reading(now,"Renamed battery",address),"new",30);store.add(reading(now,"Second battery",other),"other",30);check(store.count(address)==2,"Stable address groups renamed battery");check(store.count(other)==1,"Other battery isolated");store.add(Reading.demo());check(store.count()==3,"Demo rejected by storage itself");store.add(new Reading(now,legacy.basic,new double[0],legacy.device));check(store.count()==3,"Incomplete cells rejected");
  ByteArrayOutputStream out=new ByteArrayOutputStream();store.export(out,true,null,address,now-1000);JSONObject exported=new JSONObject(out.toString("UTF-8"));check(exported.getJSONArray("readings").length()==1,"Export respects battery and date range");check(exported.getInt("schema_version")==2,"Export schema updated");out.reset();store.export(out,false,reading(now,"=formula,quoted",address));String csv=out.toString("UTF-8");check(csv.contains("\"'=formula,quoted ["),"CSV formula and comma escaping");check(csv.split("\r\n")[0].split(",").length==63,"CSV column schema");
  ProfileStore profiles=new ProfileStore(context);ProfileStore.Profile profile=new ProfileStore.Profile(address,"My renamed battery");profile.notes="<script>alert('test')</script>";profile.alerts.enabled=true;profile.protocol="JK02_32S";profiles.put(profile);check(profiles.get(address).protocol.equals("JK02_32S"),"Protocol profile roundtrip");check(profiles.get(address).alerts.enabled,"Alert profile roundtrip");
  VictronProtocol.Data vd=new VictronProtocol.Data();vd.type=1;vd.model=0xa001;vd.counter=123;vd.state=3;vd.add("Solar power",590,"W");vd.add("Battery voltage",48.12,"V");vd.details.put("Cell 4","Below 2.61 V");EquipmentReading equipment=new EquipmentReading(now,other,"Solar charger",vd);store.equipment(equipment,30);check(store.latestEquipment(other).data.values.get("Solar power")==590,"Equipment storage roundtrip");check(store.latestEquipment(other).data.details.get("Cell 4").equals("Below 2.61 V"),"Equipment details stored without inventing clipped cell values");out.reset();store.exportEquipment(out,true);check(new JSONObject(out.toString("UTF-8")).getJSONArray("equipment_readings").length()==1,"Equipment JSON export");out.reset();store.exportEquipment(out,false);check(out.toString("UTF-8").contains("Solar charger"),"Equipment CSV export");check(out.toString("UTF-8").contains("Below 2.61 V"),"Equipment CSV exports text details");
  out.reset();store.backup(out,profiles);String backup=out.toString("UTF-8");JSONObject parsed=new JSONObject(backup);check(parsed.getJSONArray("profiles").length()==1,"Backup profiles");check(parsed.getJSONArray("readings").length()==3,"Backup BMS history");check(parsed.getJSONArray("equipment").length()==1,"Backup equipment history");check(!backup.contains("password")&&!backup.contains("readout_key"),"No credential fields in backup");check(store.restore(new ByteArrayInputStream(bytes(backup)),profiles,30)==0,"Backup merge deduplicates existing samples");
  Context restoredContext=new Context(Files.createTempDirectory("bms-restored-test-"));HistoryStore restored=new HistoryStore(restoredContext);ProfileStore restoredProfiles=new ProfileStore(restoredContext);check(restored.restore(new ByteArrayInputStream(bytes(backup)),restoredProfiles,30)==4,"All BMS and equipment samples restored");check(restored.count()==3,"Restored BMS count");check(restoredProfiles.get(address).name.equals(profile.name),"Restored profile name");check(restored.latestEquipment(other)!=null,"Restored equipment");check(restored.latestEquipment(other).data.details.get("Cell 4").equals("Below 2.61 V"),"Equipment details preserved in backup restore");
  ProfileStore.Profile existing=restoredProfiles.get(address);existing.name="Keep local name";restoredProfiles.put(existing);restored.restore(new ByteArrayInputStream(bytes(backup)),restoredProfiles,30);check(restoredProfiles.get(address).name.equals("Keep local name"),"Existing profiles kept during merge");
  JSONObject bad=new JSONObject();bad.put("backup_version",1);bad.put("profiles",new JSONArray());JSONArray badRows=new JSONArray();badRows.put(reading(now+1000,"New entry",address).json());JSONObject invalid=reading(now+2000,"Bad",address).json();invalid.put("soc_percent",999);badRows.put(invalid);bad.put("readings",badRows);int count=store.count();boolean rejected=false;try{store.restore(new ByteArrayInputStream(bytes(bad.toString())),profiles,30);}catch(Exception e){rejected=true;}check(rejected,"Invalid backup rejected");check(store.count()==count,"Invalid backup rolls back already inserted rows");
  EnergyStats stats=new EnergyStats();stats.add(now-10000,50,-2,"A");stats.add(now,50,-2,"A");store.session("session",address,profile.name,stats,"Stopped");check(store.sessions(address).size()==1,"Session summaries saved");store.event(address,"alert","Low battery");check(store.events(address).size()==1,"Alert event saved");String html=OfflineReport.create(legacy,profile,stats,store.chart(address,now-3600000),3600000);check(html.contains("&lt;script&gt;"),"Report notes HTML escaped");check(!html.contains("<script>"),"No report script execution");check(html.contains("<svg")&&!html.contains("https://"),"Report charts self-contained");
  store.clear(address);check(store.count(address)==0&&store.count(other)==1,"Per-battery deletion isolates other battery");check(store.sessions(address).isEmpty()&&store.events(address).isEmpty(),"Per-battery session/event deletion");store.clear();check(store.count()==0&&store.latestEquipment(other)==null,"Delete all clears both history types");store.close();restored.close();System.out.println("PASS: "+checks+" storage, upgrade, backup and report checks on host SQLite (Android lifecycle not simulated)");
 }
}
